/**
 * doc-header.ts — the generation header of Inspector documents (0.13.0). Pure functions;
 * the writer is `inspection-state.ts stamp-docs`, which owns `.ono/state.json`.
 *
 * Every Inspector-generated document carries exactly one line at a fixed location:
 *
 *   Generated by ono-project-inspector 0.13.0 · knowledge at a1b2c3d · updated 2026-11-24
 *
 * Location: directly below the document's H1 when its first non-empty line is an H1
 * (`# …`), separated by one blank line; otherwise as the first line of the file. Nothing
 * else in the document is moved, rewritten or removed.
 *
 *   version          the installed plugin's .claude-plugin/plugin.json version
 *   knowledge at     7-character commit of the source baseline the content reflects:
 *                    CLAUDE.md / AUDIT.md -> project-analysis knowledgeHead,
 *                    docs/project/*       -> project-docs knowledgeHead,
 *                    audits/**            -> HEAD when the audit was (re)written;
 *                    `unknown` when that baseline is not established — never guessed
 *   updated          UTC date of the last change to the document's body (everything but
 *                    the header line); an unchanged body keeps its date
 *
 * Header lines are only recognised (and de-duplicated) in the document's top region —
 * before its first `## ` heading — so a similar line in developer-written body text is
 * never touched.
 *
 * Bytes (0.14.0): the header and its blank line are spliced in with the line ending of the
 * line they attach to (the H1, or the first line), so an LF document stays LF, a CRLF
 * document (Git for Windows, core.autocrlf=true) stays CRLF, and a mixed document changes
 * only at the insertion point. A UTF-8 BOM stays the first character of the file, and an H1
 * right after it is recognised as the H1. Nothing else in the document is touched.
 */

import { createHash } from "crypto";
import { UTF8_BOM, canonicalSha256, crOf, toLf } from "./markdown-text.ts";

export const HEADER_PREFIX = "Generated by ono-project-inspector ";
export const HEADER_RE = /^Generated by ono-project-inspector ([^\s·]+) · knowledge at ([0-9a-f]{7}|unknown) · updated (\d{4}-\d{2}-\d{2})\r?$/;

export interface Header { version: string; knowledgeCommit: string; updated: string }

export function headerLine(h: Header): string {
  return `${HEADER_PREFIX}${h.version} · knowledge at ${h.knowledgeCommit} · updated ${h.updated}`;
}

export function parseHeader(line: string): Header | null {
  const m = HEADER_RE.exec(line);
  return m ? { version: m[1], knowledgeCommit: m[2], updated: m[3] } : null;
}

/** 7-character commit id, or `unknown` when there is no established baseline. */
export const shortCommit = (sha: string | null | undefined): string => (sha && /^[0-9a-f]{7,40}$/.test(sha) ? sha.slice(0, 7) : "unknown");

export const todayUtc = (): string => new Date().toISOString().slice(0, 10);

export const sha256 = (text: string): string => createHash("sha256").update(text, "utf-8").digest("hex");

/** Index of the first `## ` heading (end of the top region), or the line count. */
function topRegionEnd(lines: string[]): number {
  const i = lines.findIndex((l) => /^##\s/.test(l));
  return i === -1 ? lines.length : i;
}

/** A line with a leading UTF-8 BOM removed (only the file's first line can carry one). */
const unBom = (line: string): string => (line.startsWith(UTF8_BOM) ? line.slice(1) : line);

/** The header found in the top region (the first one, if several), or null. */
export function findHeader(text: string): Header | null {
  const lines = text.split("\n");
  const end = topRegionEnd(lines);
  for (let i = 0; i < end; i++) {
    const h = parseHeader(i === 0 ? unBom(lines[i]) : lines[i]);
    if (h) return h;
  }
  return null;
}

/**
 * The document body: the text with every top-region header line removed, together with
 * the one blank line stamping inserted after it. Inverse of insertHeader().
 */
export function stripHeader(text: string): string {
  const lines = text.split("\n");
  const bom = lines[0].startsWith(UTF8_BOM);
  const end = topRegionEnd(lines);
  const out: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = i === 0 ? unBom(lines[i]) : lines[i];
    if (i < end && parseHeader(line)) {
      if (i + 1 < end && lines[i + 1].replace(/\r$/, "") === "") i++; // the blank line that followed it
      continue;
    }
    out.push(line);
  }
  // A BOM stays the first character of the file, whichever line follows it now.
  return (bom ? UTF8_BOM : "") + out.join("\n");
}

/** Where the header goes: "after-h1" or "top". */
export function placement(body: string): "after-h1" | "top" {
  const lines = body.split("\n");
  const first = lines.findIndex((l) => unBom(l).trim() !== "");
  return first !== -1 && /^#\s/.test(first === 0 ? unBom(lines[first]) : lines[first]) ? "after-h1" : "top";
}

/**
 * The line ending to use next to line `i`: that line's own ending; for a last line without
 * one, the ending of the line before it; for a one-line document, LF.
 */
function localCr(lines: string[], i: number): "\r" | "" {
  if (i < lines.length - 1) return crOf(lines[i]);
  return i > 0 ? crOf(lines[i - 1]) : "";
}

/** Insert exactly one header into a header-free body, at the fixed location. */
export function insertHeader(body: string, h: Header): string {
  const lines = body.split("\n");
  const line = headerLine(h);
  if (placement(body) === "after-h1") {
    const i = lines.findIndex((l) => unBom(l).trim() !== "");
    const cr = localCr(lines, i);
    // An H1 that ends the file without a newline gets one (in the document's style) before the header.
    const h1 = i === lines.length - 1 ? lines[i] + cr : lines[i];
    // A blank line already below the H1 is kept, byte for byte, as the separator above the header,
    // and the header gets its own blank line below; stripHeader() removes exactly the header and
    // that blank line, so strip(insert(body)) === body whatever line ending that blank line has.
    // (For LF and uniformly CRLF documents this is the same output as inserting a new blank.)
    if (i + 1 < lines.length - 1 && lines[i + 1].replace(/\r$/, "") === "") {
      return [...lines.slice(0, i), h1, lines[i + 1], line + cr, cr, ...lines.slice(i + 2)].join("\n");
    }
    return [...lines.slice(0, i), h1, cr, line + cr, ...lines.slice(i + 1)].join("\n");
  }
  const bom = lines[0].startsWith(UTF8_BOM);
  const cr = localCr(lines, 0);
  return (bom ? UTF8_BOM : "") + [line + cr, cr, unBom(lines[0]), ...lines.slice(1)].join("\n");
}

/** Documents the Inspector generates and may stamp; everything else is never touched. */
export function isStampable(rel: string, produced: string[]): boolean {
  if (/^audits\/[^/]+\/[^/]+\.md$/.test(rel)) return true;
  return produced.includes(rel) && rel.endsWith(".md");
}

/**
 * The hash recorded for a document body (state.json `documents.<rel>.bodySha256`): canonical
 * (`sha256-lf`) since 0.14.0, so the same body hashes identically on LF and CRLF checkouts.
 * For a body stored with LF it is exactly the hash 0.13.0 recorded.
 */
export const bodyHash = (body: string): string => canonicalSha256(body);

/**
 * Whether a recorded body hash describes `body` — the same content, whatever line endings
 * it was hashed with. Recognised encodings of the one LF-normalized body:
 *   1. canonical (0.14.0 records; equally every 0.13.0 record written from an LF body);
 *   2. the body exactly as read now (a 0.13.0 record written on this same checkout);
 *   3. the body with every line ending CRLF (a 0.13.0 record written on a CRLF checkout of a
 *      document that is read from an LF checkout now);
 *   4. as 3, except that the blank line below the H1 ends in LF: the body 0.13.0 recorded
 *      after stamping a CRLF document (its header insertion wrote that line with LF).
 * Each candidate is a deterministic encoding of the same normalized text, so any change to
 * the content itself changes every candidate: content integrity is not weakened. A record
 * of a mixed-ending body that matches none of these is treated as changed (conservative).
 */
export function bodyHashMatches(recorded: string, body: string): boolean {
  const lf = toLf(body);
  if (recorded === sha256(lf) || recorded === sha256(body)) return true;
  const lines = lf.split("\n");
  if (recorded === sha256(lines.join("\r\n"))) return true;
  if (placement(lf) === "after-h1") {
    const i = lines.findIndex((l) => unBom(l).trim() !== "");
    if (lines[i + 1] === "" && i + 2 < lines.length) {
      const legacy = lines.slice(0, i + 2).join("\r\n") + "\n" + lines.slice(i + 2).join("\r\n");
      if (recorded === sha256(legacy)) return true;
    }
  }
  return false;
}
